// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz: an arbitrary attacker address and arbitrary deposit amount
    function testFuzz_property(address attacker, uint256 deposit) public {
        // keep deposit in a wide, sensible range but allow zero
        deposit = bound(deposit, 0, 1 ether);

        // fund attacker so they can call withdraw if needed
        vm.deal(attacker, deposit + 1 ether);

        // Make the contract hold some balance by sending deposit from attacker
        if (deposit > 0) {
            vm.prank(attacker);
            // deposit into contract using receive()
            (bool sent, ) = address(c).call{value: deposit}("");
            require(sent);
        }

        // record balance before withdraw
        uint256 before = address(c).balance;

        // now have the attacker call withdraw
        vm.prank(attacker);
        bool ok;
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After the call: in the correct contract, if caller != Owner then withdraw must not transfer funds away
        // So for any attacker (fuzzed) the contract balance must be equal to before whenever the caller is not Owner.
        // We observe Owner via c.Owner() and address(c).balance
        address owner = c.Owner();

        if (attacker != owner) {
            // Exactly one assertion as required: the reference satisfies this for all inputs,
            // the mutant (which allows anyone to drain) will be caught for some inputs by the fuzzer.
            assertTrue(address(c).balance == before);
        } else {
            // If attacker is owner, behavior may drain the balance; in that case we still must assert a true statement
            // that holds for both reference and mutant. The reference allows owner to withdraw -> contract balance becomes 0.
            // The mutant also transfers to Owner (same). So require the post-state is either 0 or unchanged depending on ok.
            // To keep a single assert line required by the harness and ensure it always holds for the reference,
            // we assert that if the call did not revert (ok==true) then contract balance is <= before (monotonic non-increase).
            assertTrue(ok ? (address(c).balance <= before) : (address(c).balance == before));
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: caller address and deposit amount
    function testFuzz_property(address caller, uint256 amount) public {
        // keep amount in a reasonable range but wide (up to 1e18)
        amount = bound(amount, 0, 1 ether);

        // ensure caller is not the owner address (owner is address(this) at deployment)
        // but allow the fuzzer to still sometimes pick the owner: the universal property
        // must hold for all inputs; if caller==owner then withdraw should still succeed
        // and drain balance — property still holds since caller is owner.

        // Fund the caller so they can send ETH
        vm.deal(caller, amount);

        // send some ETH into the contract to be withdrawable
        uint256 seedDeposit = 0.5 ether;
        vm.deal(address(this), seedDeposit);
        // deposit seedDeposit into c from this test contract (owner)
        c.Command{value: seedDeposit}(address(0), ""); // safe call: Command will call address(0) with empty data and value; address(0) call is no-op but transfers value into c because Command is payable and forwards value
        // Note: if Command forwarding to address(0) reverts on some clients, as a simpler guaranteed deposit we can use .call directly by sending ether to c via address(c).call
        // but solidity allows payable receive, so instead do a direct transfer to c
        // (above approach used to avoid using low-level from test; to be safe, ensure deposit by direct call):
        (bool sent,) = address(c).call{value: seedDeposit}("");
        require(sent);

        // snapshot balance before withdraw
        uint256 before = address(c).balance;
        // sanity: require there is some balance to withdraw; if none, calling withdraw can't change it
        vm.assume(before > 0);

        // Have the fuzzed caller attempt to call withdraw
        vm.prank(caller);
        // try/catch to capture whether the call reverted or not
        bool ok;
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: if the caller was not the Owner, then after calling withdraw the contract's balance must still be equal to before.
        // This is the universal property the reference satisfies (only Owner can drain); the mutant removes the require and allows non-owner to drain.
        if (caller != address(this)) {
            // If call did not revert but caller is not owner, the reference guarantees balance unchanged (withdraw should revert in reference or not transfer away funds)
            // We assert the balance remained the same.
            assertTrue(address(c).balance == before);
        } else {
            // If caller is owner, withdraw may succeed and drain the balance; in that case balance is allowed to be zero.
            // Assert that the balance is either unchanged or zero (both acceptable for owner call), ensuring single assertTrue overall by encoding as boolean.
            assertTrue(address(c).balance == before || address(c).balance == 0);
        }
    }
}

