pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: an address that will attempt to call withdraw, and an amount to fund the contract
    function testFuzz_property(address caller, uint256 fundAmount) public {
        // keep fundAmount in a reasonable wide range but not zero so there's something to withdraw
        fundAmount = bound(fundAmount, 1, 1 ether);

        // ensure caller has funds to send (even though withdraw is not payable with value, we only need caller to exist)
        vm.deal(caller, 1 ether);

        // fund the contract from the Owner (setUp deployer is this test contract's address by default)
        // the Owner is the deployer (this test contract), so send funds to c from address(this)
        vm.deal(address(this), fundAmount);
        // send funds to the contract
        (bool sent,) = address(c).call{value: fundAmount}(
            abi.encodeWithSignature("")
        );
        require(sent, "funding failed");

        // If caller == Owner (address(this) is the Owner), a withdraw should succeed.
        // If caller != Owner, in the correct contract withdraw should revert (require fails).
        bool ok;
        vm.prank(caller);
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: withdraw succeeds iff caller is the Owner. This holds for the reference C for all inputs.
        // The mutant that removes the require will allow a non-owner caller to succeed, breaking this rule.
        assertTrue(ok == (caller == address(this)));
    }
}

