pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: caller (an address) and incoming funding amount
    function testFuzz_property(address caller, uint256 fundAmount) public {
        // keep fundAmount in a reasonable wide range but nonzero so there's something to withdraw
        fundAmount = bound(fundAmount, 1, 1 ether);

        // The caller must not be the owner (owner is this contract deployer, i.e., address(this) since setUp used new C())
        // fuzzed `caller` could equal address(this); avoid that so we test the non-owner case
        vm.assume(caller != address(this));

        // Fund the contract with fundAmount from the Owner (address(this)) so contract has balance
        vm.deal(address(this), fundAmount);
        c.Command{value: fundAmount}(address(this), ""); // route value into contract via Command (Owner-only) to fund it

        // Sanity: contract has balance
        assert(address(c).balance == fundAmount);

        // Now attempt withdraw as the fuzzed non-owner caller
        vm.deal(caller, 0.1 ether);
        vm.prank(caller);
        bool ok;
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): For the correct contract, a non-owner caller cannot remove the contract balance.
        // Therefore after the non-owner's attempt, the contract balance must still equal the original fundAmount.
        // The mutant (which removed the require) allows a non-owner to drain the contract; the assertion will fail on that mutant for some fuzz inputs.
        assertTrue(address(c).balance == fundAmount);
    }
}

