pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: amount to seed the contract and an arbitrary recipient address (fuzzer will choose)
    function testFuzz_property(uint256 seedAmount, address recipient) public {
        // Keep seedAmount in a reasonable range but allow zero as well.
        seedAmount = bound(seedAmount, 0, 1 ether);

        // The Owner is the deployer created in setUp() (this contract). We will fund the contract and then call withdraw as Owner.
        // Fund the contract from an external EOA (player) so balances move realistically.
        address player = address(0xBEEF);
        vm.deal(player, 2 ether);

        // Player funds the contract with seedAmount
        vm.prank(player);
        (bool sent,) = address(c).call{value: seedAmount}(""); // uses receive()
        require(sent);

        // Record balances before withdraw
        uint256 ownerBefore = address(this).balance; // this test contract is Owner
        uint256 contractBefore = address(c).balance;

        // Ensure contract has the expected seeded amount
        assert(contractBefore == seedAmount);

        // As Owner (this contract) call withdraw()
        vm.prank(address(this));
        c.withdraw{value: 0}();

        // After withdraw, the correct contract should have forwarded the entire balance to Owner
        // General rule: address(c).balance == 0 after Owner calls withdraw()
        assertTrue(address(c).balance == 0);
    }
}

