contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: amount to fund the contract, and an address to act as the caller.
    // The deciding values are whether the caller is the Owner (must be) and the contract has a positive balance.
    function testFuzz_property(uint256 fundAmount, address caller) public {
        // Keep fundAmount in a sensible wide range but nonzero so the transfer/emptying behavior matters
        fundAmount = bound(fundAmount, 1, 1 ether);

        // The Owner in the reference contract is the deployer (this test contract's address at setUp time),
        // which is address(this) here because setUp deployed c from this contract.
        address owner = address(this);

        // We must ensure the withdraw call is invoked by the Owner; the fuzzer provides `caller`, so constrain it
        // to be the Owner. This still uses a fuzz parameter (caller) but restricts admissible domain.
        vm.assume(caller == owner);

        // Fund the caller so it can send Ether to c.
        vm.deal(caller, fundAmount);

        // Have the Owner send Ether to the contract c (using its receive())
        vm.prank(caller);
        (bool sent, ) = address(c).call{value: fundAmount}("\x00");
        // call to fund should succeed in normal EVM; assume it did
        vm.assume(sent);

        // Sanity: contract has positive balance before withdraw
        assert(address(c).balance == fundAmount);

        // Now perform withdraw() as the Owner (caller)
        bool ok;
        vm.prank(caller);
        try c.withdraw{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule (single assertion): after withdraw by the stored Owner, the contract's balance is zero
        // Reference C satisfies this for all admissible inputs; the mutant that transfers to msg.sender (instead of Owner)
        // will violate this for some input (the fuzzer will find such a case when run against the mutant).
        assertTrue(address(c).balance == 0);
    }
}

