pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzzed params: amount to seed contract and owner address (must be the Owner)
    function testFuzz_property(uint256 seedAmount, address ownerEOA) public {
        // keep seedAmount within a reasonable range but allow zero as well
        seedAmount = bound(seedAmount, 0, 1 ether);
        // ownerEOA must be non-zero and we require it equals the deployed Owner to be admissible
        vm.assume(ownerEOA != address(0));

        // The contract sets Owner = msg.sender at deployment (setUp()), so the Owner is address(this) of the test run that deployed it
        // We need ownerEOA to be that Owner to exercise withdraw as Owner. The deployed contract's Owner is the test contract address (address(this)).
        // Ensure fuzzed ownerEOA equals the actual Owner; if not, this input is inadmissible for our universal rule.
        vm.assume(ownerEOA == address(this));

        // Fund the owner EOA and the contract so balances change are observable
        if (seedAmount > 0) {
            vm.deal(address(this), seedAmount);
            // send Ether into the contract from this Owner address
            c.receive{value: seedAmount}();
        }

        // Record Owner balance and contract balance before withdraw
        uint256 ownerBalBefore = address(this).balance;
        uint256 contractBalBefore = address(c).balance;

        // Owner calls withdraw (msg.sender must be Owner)
        // use vm.prank to ensure the call originates from the Owner (which is address(this))
        vm.prank(address(this));
        // wrap call in try/catch to ensure we observe success; withdraw is payable but should not revert
        bool ok;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // After a successful withdraw on the correct contract, the Owner's balance must have increased by exactly the contract's prior balance
        // If the call reverted, the property is vacuously true for the correct contract, but revert is unexpected; ensure success
        // Only assert when call succeeded (the reference always allows Owner to withdraw, so it should succeed)
        if (ok) {
            uint256 ownerBalAfter = address(this).balance;
            // exactly one assertion about c's behavior: that Owner's balance increased by contractBalBefore
            assertTrue(ownerBalAfter == ownerBalBefore + contractBalBefore);
        } else {
            // if call reverted, fail the assertion because reference should not revert for Owner
            assertTrue(false);
        }
    }
}

