import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: funder address (who sends ether to the contract) and amount to fund
    function testFuzz_property(address funder, uint256 amount) public {
        // keep funder as a non-zero address (EOA) and amount in a sensible range but wide
        vm.assume(funder != address(0));
        amount = bound(amount, 1, address(this).balance + 1 ether);

        // funder must hold the ETH to send
        vm.deal(funder, amount);

        // funder sends funds to the contract via a plain transfer (receive)
        vm.prank(funder);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        // ensure contract has nonzero balance before withdraw
        assert(address(c).balance == amount);

        // Owner (deployer of c) calls withdraw
        // set a prank to the Owner (which is address(this)? Actually c's Owner is msg.sender at construction -> setUp used test contract)
        // Our test contract deployed c in setUp(), so address(this) is Owner
        // call withdraw as Owner
        vm.prank(address(this));
        c.withdraw{value: 0}();

        // The single assertion: in the reference contract withdraw empties the contract
        // so balance must be exactly zero; the mutant that sends half will leave positive balance
        assertTrue(address(c).balance == 0);
    }
}

