contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address and an amount to send to the contract before withdraw.
    // The distinguishing input is when the Owner calls withdraw. Owner is c.Owner() so we fuzz an address but
    // will use the actual owner returned by the contract to perform the decisive call.
    function testFuzz_property(address caller, uint256 preFund) public {
        // keep preFund within a reasonable range but wide
        preFund = bound(preFund, 0, 10 ether);

        // Ensure the caller has funds to send if needed
        vm.deal(caller, preFund + 1 ether);

        // Fund the contract from some arbitrary caller to create non-zero balance scenario
        vm.prank(caller);
        (bool okFund,) = address(c).call{value: preFund}(abi.encodeWithSignature(""));
        // funding may succeed or be zero; we proceed regardless

        // Now arrange for the Owner to call withdraw. Owner is c.Owner()
