        // Ensure owner has some ETH to be able to call (even if not strictly required)
        vm.deal(owner, 1 ether);

        // Call withdraw as Owner and capture whether it succeeded (did not revert)
        bool ok;
        vm.prank(owner);
        try c.withdraw{value: 0}() {
            ok = true;
