        // General rule (single assertion): In the correct contract, the Owner can always call withdraw successfully.
        // This will be true for the reference implementation for all inputs; the mutant that adds require(msg.sender != Owner)
        // will make this false for the Owner call (ok == false) for some inputs and thus the test will fail on the mutant.
        assertTrue(ok);
    }
